argv:
mkdir -p /workspace/reports && cat > /workspace/arithmetic.eval.json <<'EOF'
{
  "schemaVersion": "2",
  "mode": "agentWorkflow",
  "reportingMode": "standard",
  "suite": {"id": "s_arithmetic_smoke", "name": "Arithmetic smoke"},
  "target": {"servers": [{"name": "Arithmetic"}]},
  "defaults": {
    "judge": {"enabled": false},
    "model": "openai/gpt-4.1-mini",
    "iterations": 1,
    "passThreshold": 1,
    "validity": {}
  },
  "cases": [{
    "id": "c_add_17_25",
    "title": "Add 17 and 25 to obtain 42",
    "steps": [
      {"id": "s1", "kind": "prompt", "prompt": "Use the add tool to add 17 and 25. Report the result."},
      {"id": "a1", "kind": "assert", "assertion": {"type": "toolCalledWith", "toolName": "add", "args": {"a": 17, "b": 25}}},
      {"id": "a2", "kind": "assert", "assertion": {"type": "noToolErrors"}},
      {"id": "a3", "kind": "assert", "assertion": {"type": "toolResultMatchesSchema", "toolName": "add", "schema": {"type": "object", "properties": {"sum": {"const": 42}}, "required": ["sum"]}}}
    ]
  }]
}
EOF
npx mcpjam cloud eval validate --file arithmetic.eval.json --project project_fixture --format json > reports/validation.json && cat reports/validation.json && npx mcpjam cloud eval run --file arithmetic.eval.json --project project_fixture --wait --wait-timeout 60000 --out reports/eval.json --format json > reports/launch.json
